#include "api/registry.h"

#include <mutex>

// Generated by CMake from src/**/*_register.cpp (one RIG_MODULE(name) line per file).
#define RIG_MODULE(name) void rig_register_##name(rig::Registry &);
#include "rig_modules.inc"
#undef RIG_MODULE

namespace rig {
namespace {

template <class V, class K>
auto *best(const V &v, K matches) {
  const typename V::value_type *b = nullptr;
  for (const auto &e : v)
    if (matches(e) && (!b || e.priority >= b->priority)) b = &e;
  return b;
}

}  // namespace

Registry &Registry::global() {
  static Registry r;
  return r;
}

void Registry::addUnit(std::string_view kind, UnitFactory f, UnitInfo info, int priority) {
  units_.push_back({std::string(kind), f, info, priority});
}

void Registry::addSetHandler(std::string_view prefix, SetHandler h, int priority) {
  sets_.push_back({std::string(prefix), h, priority});
}

void Registry::addService(std::string_view name, ServiceFactory f, int priority) {
  services_.push_back({std::string(name), f, priority});
}

const Registry::UnitEntry *Registry::unit(std::string_view kind) const {
  return best(units_, [&](const UnitEntry &e) { return e.kind == kind; });
}

const Registry::ServiceEntry *Registry::service(std::string_view name) const {
  return best(services_, [&](const ServiceEntry &e) { return e.name == name; });
}

const Registry::SetEntry *Registry::setHandler(std::string_view path) const {
  const SetEntry *b = nullptr;
  for (const auto &e : sets_) {
    if (path.substr(0, e.prefix.size()) != e.prefix) continue;
    // highest priority first (modules beat builtins), then the longest prefix, then the later registration
    if (!b || e.priority > b->priority ||
        (e.priority == b->priority && e.prefix.size() >= b->prefix.size()))
      b = &e;
  }
  return b;
}

void ensureModulesRegistered() {
  static std::once_flag once;
  std::call_once(once, [] {
    Registry &r = Registry::global();
#define RIG_MODULE(name) rig_register_##name(r);
#include "rig_modules.inc"
#undef RIG_MODULE
    (void)r;
  });
}

}  // namespace rig
